#!/usr/bin/env bash
# Runs the database rule tests on a local Postgres (port 5499, socket in /tmp). Usage: bash supabase/tests/run.sh
set -euo pipefail
cd "$(dirname "$0")/.."
P="psql -h /tmp -p 5499 -U postgres -v ON_ERROR_STOP=1 -q"
$P -d postgres -c 'drop database if exists nf_test' -c 'create database nf_test'
$P -d nf_test -f tests/00_supabase_stub.sql -f migrations/0001_init.sql -f migrations/0003_simple_profiles.sql -f migrations/0004_edit_profiles.sql -f migrations/0005_chat_photos_and_online.sql -f migrations/0006_invoices.sql -f migrations/0007_calendar.sql -f migrations/0008_grants.sql -f migrations/0009_handles_cards.sql -f migrations/0010_founding_pros.sql -f migrations/0011_social.sql -f migrations/0012_urgent.sql -f migrations/0013_figure.sql -f migrations/0014_community.sql -f migrations/0015_pro_controls_neighbors.sql -f migrations/0016_photo_search.sql -f migrations/0017_job_parts.sql -f migrations/0018_quotes_orders.sql -f migrations/0019_trust_social.sql -f migrations/0020_requests_demo.sql -f migrations/0021_review_weights.sql -f migrations/0022_terms.sql -f migrations/0023_discovery.sql -f migrations/0024_contact_invites.sql -f migrations/0025_service_area.sql -f migrations/0026_service_polygon.sql -f migrations/0027_custom_services.sql -f migrations/0028_trade_requests.sql -f migrations/0029_own_trade.sql -f migrations/0030_license_check.sql -f migrations/0031_cslb_list.sql -f migrations/0032_jobs_wait_license.sql -f migrations/0033_clean_words.sql -f migrations/0034_english_only.sql -f migrations/0035_quiet_new_chats.sql -f migrations/0036_external_profiles.sql -f migrations/0037_friends.sql -f migrations/0038_helpers_tips.sql -f migrations/0039_quote_duration.sql -f migrations/0040_calls.sql -f migrations/0041_online_spot.sql -f seed.sql -f tests/zz_grants_for_test.sql
$P -d nf_test -f tests/01_rules_test.sql 2>&1 | grep -E 'ok  |FAIL|ERROR|PASSED'
